#!/usr/bin/env python3
"""Build the f84-free executable joint-tuple interlinear and atlas."""
import csv, hashlib, json, math
from collections import Counter, defaultdict
from pathlib import Path
import numpy as np
R=Path(__file__).resolve().parent;SOURCE=R/'gdt278_native_event_inventory.tsv';LEX=R/'gdt322_opaque_cell_lexicon.tsv';MODEL=R/'gdt322_renderer_model.json';METHOD=R/'GDT327_JOINT_TUPLE_INTERLINEAR_METHOD.md';INTER=R/'gdt327_joint_tuple_interlinear.tsv';ATLAS=R/'gdt327_joint_tuple_atlas.tsv';GRAMMAR=R/'gdt327_executable_grammar.json';REPORT=R/'GDT327_JOINT_TUPLE_INTERLINEAR_REPORT.md';RESULT=R/'gdt327_result.json';COORD=('local_frame','inner_d','right_family','dy_closure','b3')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def can(v):return hashlib.sha256(json.dumps(v,sort_keys=True,ensure_ascii=True,separators=(',',':')).encode()).hexdigest()
def read(p):
 with Path(p).open(encoding='utf8',newline='') as h:return list(csv.DictReader(h,delimiter='\t'))
def write(p,rows):
 with Path(p).open('w',encoding='utf8',newline='') as h:w=csv.DictWriter(h,rows[0].keys(),delimiter='\t',lineterminator='\n');w.writeheader();w.writerows(rows)
def hid(prefix,values):return hashlib.sha256((prefix+'|'+'|'.join(values)).encode()).hexdigest()[:20]
def main():
 rows=[x for x in read(SOURCE) if x['control_id']=='VOYNICH_REFERENCE'];assert not any(x['page'].startswith('f84') or x['locus'].startswith('f84') for x in rows);model=json.loads(MODEL.read_text());classes=model['classes'];lex={x['cell_id']:x for x in read(LEX)};positions={(x['locus'],int(x['group_index'])):x for x in rows};inter=[];members=defaultdict(list)
 for x in rows:
  coordinate=tuple(x[k] for k in COORD);cell=hid('CELL',(x['page_host'],)+coordinate);host=hid('HOST',(x['page_host'],));coord=hid('COORD',coordinate);previous=positions.get((x['locus'],int(x['group_index'])-1));line=int(x['group_index']=='1');prev=int(previous is not None and previous['dy_closure']=='1');state='EXECUTABLE_POWERED_CELL' if cell in lex else 'UNLICENSED_OR_UNKNOWN';probability='';surprisal='';probjson=''
  if cell in lex:
   counts=json.loads(lex[cell]['wrapper_counts_json']);scores=np.array([math.log(counts[w]+model['alpha']) for w in classes]);scores[classes.index('s')]+=model['beta_s_line_first']*line;scores[classes.index('q')]+=model['beta_q_prev_dy']*prev;scores-=scores.max();p=np.exp(scores);p/=p.sum();probability=f"{p[classes.index(x['wrapper'])]:.12f}";surprisal=f"{-math.log2(max(p[classes.index(x['wrapper'])],1e-15)):.12f}";probjson=json.dumps({w:round(float(p[i]),12) for i,w in enumerate(classes)},sort_keys=True,separators=(',',':'))
  event={'event_id_sha256':hashlib.sha256(x['observation_id'].encode()).hexdigest()[:20],'page':x['page'],'physical_folio':x['physical_folio'],'locus':x['locus'],'group_index':x['group_index'],'group_count':x['group_count'],'section':x['section'],'register':x['register'],'currier':x['currier'],'hand':x['hand'],'record_ordinal':x['record_ordinal'],'field_ordinal':x['field_ordinal'],'within_field_position':x['within_field_position'],'joint_tuple_id':cell,'host_id':host,'coordinate_id':coord,'observed_wrapper':x['wrapper'],'line_first':line,'prev_dy':prev,'dy_closure':x['dy_closure'],'b3':x['b3'],'known_label_renderer':x['known_label_renderer'],'renderer_state':state,'observed_wrapper_probability':probability,'observed_wrapper_surprisal_bits':surprisal,'wrapper_probabilities_json':probjson,'semantic_state':'UNASSIGNED','translation_state':'UNASSIGNED'};inter.append(event);members[cell].append((x,event))
 write(INTER,inter);atlas=[]
 for cell,items in sorted(members.items()):
  first,event=items[0];atlas.append({'joint_tuple_id':cell,'host_id':event['host_id'],'coordinate_id':event['coordinate_id'],'events':len(items),'folios':len({x['physical_folio'] for x,_ in items}),'sections':'|'.join(sorted({x['section'] for x,_ in items})),'registers':'|'.join(sorted({x['register'] for x,_ in items})),'wrapper_classes':'|'.join(sorted({x['wrapper'] for x,_ in items})),'renderer_state':event['renderer_state'],'semantic_state':'UNASSIGNED','translation_state':'UNASSIGNED'})
 write(ATLAS,atlas);covered=sum(x['renderer_state']=='EXECUTABLE_POWERED_CELL' for x in inter);grammar={'schema':'GDT327_EXECUTABLE_JOINT_TUPLE_GRAMMAR_V1','status':'EXECUTABLE_JOINT_TUPLE_INTERLINEAR','hierarchy':['PAGE','RECORD','PHYSICAL_LINE','FIELD','GROUP'],'group_generator':['OPAQUE_JOINT_TUPLE_PAGE_HOST_FRAME_INNERD_RIGHT_DY_B3','EXACT_CELL_COMPATIBILITY_LEXICON_IF_POWERED','S_LINE_START_SELECTOR','Q_PREV_DY_SELECTOR','VISIBLE_WRAPPER_PLUS_JOINT_TUPLE'],'formula':model['formula'],'beta_s_line_first':model['beta_s_line_first'],'beta_q_prev_dy':model['beta_q_prev_dy'],'unknown_policy':'UNLICENSED_OR_UNKNOWN_NO_COORDINATE_OR_HOST_FACTORIAL_BACKOFF','events':len(inter),'joint_tuples':len(atlas),'executable_cells':len(lex),'executable_events':covered,'coverage_fraction':covered/len(inter),'semantic_assignments':0,'translation_assignments':0,'claim_ceiling':'Formal joint-tuple interlinear only; no word morpheme POS sound language meaning plaintext or translation.','f84':{'input_rows':0,'opened':False,'parsed':False,'retained':False,'joined':False,'scored':False},'inputs':{p.name:sha(p) for p in (SOURCE,LEX,MODEL,R/'gdt325_result.json',R/'gdt326_result.json',METHOD)},'outputs':{p.name:sha(p) for p in (INTER,ATLAS)},'implementation':{Path(__file__).name:sha(Path(__file__))}};grammar['content_sha256']=can(grammar);GRAMMAR.write_text(json.dumps(grammar,indent=2,sort_keys=True)+'\n');report=['# GDT327 — executable joint-tuple interlinear','',f"Status: **{grammar['status']}**.",'',f"The f84-free interlinear contains {len(inter):,} physical source groups and {len(atlas):,} opaque joint tuples on {len({x['physical_folio'] for x in inter})} folios. The calibrated 126-cell lexicon covers {covered:,} events ({100*covered/len(inter):.1f}%); {len(inter)-covered:,} events remain explicitly `UNLICENSED_OR_UNKNOWN`.",'','```text','PAGE -> RECORD+ -> PHYSICAL_LINE+ -> FIELD+ -> GROUP+','GROUP -> JOINT_TUPLE(PAGE_HOST, FRAME, INNER_D, RIGHT, DY, B3)','      -> WRAPPER via exact-cell counts + s@LINE_START + q@PREV_DY','```','','GDT325 prevents coordinate fallback on sparse cells. GDT326 prevents treating PAGE_HOST as an independently recombining payload. The emitted unit is therefore the joint tuple, with semantic and translation states left unassigned.','','## Translation interface','','Future grounding must align whole fields or records to external evidence and may then attach hypotheses to stable joint-tuple sequences. The interlinear itself does not attach a gloss to any tuple.','','## Claim ceiling','',grammar['claim_ceiling']+' No f84 row was opened, parsed, retained, joined, or scored.'];REPORT.write_text('\n'.join(report)+'\n');outputs=[INTER,ATLAS,GRAMMAR,REPORT];res={'schema':'GDT327_JOINT_TUPLE_INTERLINEAR_RESULT_V1','status':grammar['status'],'summary':{'events':len(inter),'folios':len({x['physical_folio'] for x in inter}),'joint_tuples':len(atlas),'executable_cells':len(lex),'executable_events':covered,'coverage_fraction':covered/len(inter),'semantic_assignments':0,'translation_assignments':0},'claim_ceiling':grammar['claim_ceiling'],'f84':grammar['f84'],'inputs':{p.name:sha(p) for p in (SOURCE,LEX,MODEL,R/'gdt325_result.json',R/'gdt326_result.json')},'documents':{METHOD.name:sha(METHOD),REPORT.name:sha(REPORT)},'implementation':{Path(__file__).name:sha(Path(__file__))},'outputs':{p.name:sha(p) for p in outputs}};res['content_sha256']=can(res);RESULT.write_text(json.dumps(res,indent=2,sort_keys=True)+'\n');print(json.dumps({'status':res['status'],'summary':res['summary']},sort_keys=True))
if __name__=='__main__':main()
